    apply (lap_of_run tm Cc true true cho_1RB1RA_1RC1LA_1LD0LA_0RB0LD B0_1RB1RA_1RC1LA_1LD0LA_0RB0LD B1_1RB1RA_1RC1LA_1LD0LA_0RB0LD 6 10 p j' [] []).
