Lemma fire_1RB1RB_0LC0RB_0LD1LD_1RA1LC : forall t, ~ In t pins_1RB1RB_0LC0RB_0LD1LD_1RA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
