      with (l := [SWin 2; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RB_0LC0RB_0LD1LD_1RA1LC
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RB_0LC0RB_0LD1LD_1RA1LC
      with (l := [SWin 2; SCycL 2 0; SWin 1; SWinL 1]).
