    apply (lap_of_run tm Cc true true cho_1RB1RB_1LC1RA_0RB1LD_1RA0LC B0_1RB1RB_1LC1RA_0RB1LD_1RA0LC B1_1RB1RB_1LC1RA_0RB1LD_1RA0LC 4 12 p j' [] []).
