      Cc p = (StD, (Ap_Alph_10_11_11 p ++ [S0], S0, []))

    The lap is DATA, not a proof script: each branch is a list of steps for
    [Checkers/LapDecider.v], run by the kernel through [vm_compute] and
    discharged by the single theorem [srun_sound].

      interior  (cview p = (j, Some q0)):  j=0: 4 ; j=S j': 4*j'+8 steps
      overflow  (cview p = (S j, None)):   4*j+7 steps

    The interior branch closes EXACTLY (which is what feeds
    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 198 anchors.
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape Mirror.
Import FunctionalExtensionality.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter Alph_10_11_11 LapCertGlue.
Import TNF_QH.
Import LapDecider.
Import BBBT4_Statement.
Import WrapTr.
Import AnchorVisitsTr.
Import LapGlueTr.
Import TNF_QHTr.
Import ClosureTr.
Import LapGlueQHTr.
Import TNF_QHTr QHConveyorTr.
Import ListNotations.

Definition mk_1RB1RB_1LC1RB_1LD1LD_0RA0LC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1RB_1LC1RB_1LD1LD_0RA0LC.

(** 1RB1RB_1LC1RB_1LD1LD_0RA0LC *)
(** 1RB1RB_1LC1RB_1LD1LD_0RA0LC -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1RB_1LC1RB_1LD1LD_0RA0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S0 DL StC end.

(** Its mirror 1LB1LB_1RC1LB_1RD1RD_0LA0RC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DL StB
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RB_1LC1RB_1LD1LD_0RA0LC : list Instr := [(StA, S0)].
Definition tmw_1RB1RB_1LC1RB_1LD1LD_0RA0LC : TM := tm_wrap_trs tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC pins_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
Local Notation tm := tmw_1RB1RB_1LC1RB_1LD1LD_0RA0LC.

Lemma mirror_ok_1RB1RB_1LC1RB_1LD1LD_0RA0LC : mirror_tm tm_1RB1RB_1LC1RB_1LD1LD_0RA0LC = tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1RB_1LC1RB_1LD1LD_0RA0LC (p : positive) : cconf := (StD, (Ap_Alph_10_11_11 p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1RB_1LC1RB_1LD1LD_0RA0LC.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1RB_1LC1RB_1LD1LD_0RA0LC : sconf := mkC StD (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1RB_1LC1RB_1LD1LD_0RA0LC : sconf := mkC StD (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_1RB1RB_1LC1RB_1LD1LD_0RA0LC : list lstep := [SWin 4].

Lemma run_z_1RB1RB_1LC1RB_1LD1LD_0RA0LC : srun tm false true chz_1RB1RB_1LC1RB_1LD1LD_0RA0LC Z0_1RB1RB_1LC1RB_1LD1LD_0RA0LC = Some (Z1_1RB1RB_1LC1RB_1LD1LD_0RA0LC, 0, 4).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_1RB1RB_1LC1RB_1LD1LD_0RA0LC : sconf := mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB1RB_1LC1RB_1LD1LD_0RA0LC : sconf := mkC StD (mkS [S1;S0] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chp_1RB1RB_1LC1RB_1LD1LD_0RA0LC : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_p_1RB1RB_1LC1RB_1LD1LD_0RA0LC : srun tm false true chp_1RB1RB_1LC1RB_1LD1LD_0RA0LC P0_1RB1RB_1LC1RB_1LD1LD_0RA0LC = Some (P1_1RB1RB_1LC1RB_1LD1LD_0RA0LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1RB_1LC1RB_1LD1LD_0RA0LC : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1RB_1LC1RB_1LD1LD_0RA0LC : sconf := mkC StD (mkS [] [S1;S0] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition cho_1RB1RB_1LC1RB_1LD1LD_0RA0LC : list lstep := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 2; SWinR 1; SUnrotL 1; SFoldL 1].

Lemma run_ovf_1RB1RB_1LC1RB_1LD1LD_0RA0LC : srun tm true true cho_1RB1RB_1LC1RB_1LD1LD_0RA0LC B0_1RB1RB_1LC1RB_1LD1LD_0RA0LC = Some (B1_1RB1RB_1LC1RB_1LD1LD_0RA0LC, 4, 7).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RB_1LC1RB_1LD1LD_0RA0LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_1RB1RB_1LC1RB_1LD1LD_0RA0LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_1RB1RB_1LC1RB_1LD1LD_0RA0LC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_1LC1RB_1LD1LD_0RA0LC, cden, Z0_1RB1RB_1LC1RB_1LD1LD_0RA0LC, Z1_1RB1RB_1LC1RB_1LD1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RB_1LC1RB_1LD1LD_0RA0LC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_1RB1RB_1LC1RB_1LD1LD_0RA0LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P1_1RB1RB_1LC1RB_1LD1LD_0RA0LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_1LC1RB_1LD1LD_0RA0LC, cden, P0_1RB1RB_1LC1RB_1LD1LD_0RA0LC, P1_1RB1RB_1LC1RB_1LD1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RB_1LC1RB_1LD1LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RB_1LC1RB_1LD1LD_0RA0LC p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RB_1LC1RB_1LD1LD_0RA0LC Z0_1RB1RB_1LC1RB_1LD1LD_0RA0LC Z1_1RB1RB_1LC1RB_1LD1LD_0RA0LC 0 4
               run_z_1RB1RB_1LC1RB_1LD1LD_0RA0LC (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RB_1LC1RB_1LD1LD_0RA0LC p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RB_1LC1RB_1LD1LD_0RA0LC P0_1RB1RB_1LC1RB_1LD1LD_0RA0LC P1_1RB1RB_1LC1RB_1LD1LD_0RA0LC 4 8
               run_p_1RB1RB_1LC1RB_1LD1LD_0RA0LC (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1RB_1LC1RB_1LD1LD_0RA0LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_1RB1RB_1LC1RB_1LD1LD_0RA0LC, cden, B0_1RB1RB_1LC1RB_1LD1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RB_1LC1RB_1LD1LD_0RA0LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RB_1LC1RB_1LD1LD_0RA0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_1LC1RB_1LD1LD_0RA0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RB_1LC1RB_1LD1LD_0RA0LC
             = (StD, (rep [S1;S0] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_1RB1RB_1LC1RB_1LD1LD_0RA0LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1RB_1LC1RB_1LD1LD_0RA0LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RB_1LC1RB_1LD1LD_0RA0LC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1RB_1LC1RB_1LD1LD_0RA0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RB_1LC1RB_1LD1LD_0RA0LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RB_1LC1RB_1LD1LD_0RA0LC B0_1RB1RB_1LC1RB_1LD1LD_0RA0LC B1_1RB1RB_1LC1RB_1LD1LD_0RA0LC 4 7 p j' [] []).
    + exact run_ovf_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RB_1LC1RB_1LD1LD_0RA0LC p j' E).
    + exact (geo_1RB1RB_1LC1RB_1LD1LD_0RA0LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1RB_1LC1RB_1LD1LD_0RA0LC : stepn tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC 3 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC 3 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1RB_1LC1RB_1LD1LD_0RA0LC : existsb (fun tg => cfires tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC c0 3 tg) pins_1RB1RB_1LC1RB_1LD1LD_0RA0LC = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RB_1LC1RB_1LD1LD_0RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_1LC1RB_1LD1LD_0RA0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RB_1LC1RB_1LD1LD_0RA0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RB_1LC1RB_1LD1LD_0RA0LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RB_1LC1RB_1LD1LD_0RA0LC : forall t, ~ In t pins_1RB1RB_1LC1RB_1LD1LD_0RA0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RB_1LC1RB_1LD1LD_0RA0LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RB_1LC1RB_1LD1LD_0RA0LC
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RB_1LC1RB_1LD1LD_0RA0LC
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RB_1LC1RB_1LD1LD_0RA0LC
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RB_1LC1RB_1LD1LD_0RA0LC
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RB_1LC1RB_1LD1LD_0RA0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RB_1LC1RB_1LD1LD_0RA0LC
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_1RB1RB_1LC1RB_1LD1LD_0RA0LC : NonHalt tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC /\ QHBoundTr 32779478 tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC /\ QuasiHaltsTr tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
Proof.
  apply (lap_qh_stage tmm_1RB1RB_1LC1RB_1LD1LD_0RA0LC pins_1RB1RB_1LC1RB_1LD1LD_0RA0LC Cc 1 3 32779478).
  - exact bootq_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
  - intros p _. apply lap_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
  - intros t Ht p _. apply fire_1RB1RB_1LC1RB_1LD1LD_0RA0LC. exact Ht.
  - exact wit_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
  - vm_cast_no_check (eq_refl true).
Qed.

Theorem qhtr_1RB1RB_1LC1RB_1LD1LD_0RA0LC : NonHalt tm_1RB1RB_1LC1RB_1LD1LD_0RA0LC /\ QHBoundTr 32779478 tm_1RB1RB_1LC1RB_1LD1LD_0RA0LC /\ QuasiHaltsTr tm_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB1RB_1LC1RB_1LD1LD_0RA0LC). rewrite mirror_ok_1RB1RB_1LC1RB_1LD1LD_0RA0LC. exact qhtrm_1RB1RB_1LC1RB_1LD1LD_0RA0LC. Qed.

End LAPQ_1RB1RB_1LC1RB_1LD1LD_0RA0LC.
